class H{int C,v[];String s(boolean p,String[]L){C=L[0].length();int N=L.length*C,n=0,a=N,b,q;v=new int[N];for(;a-->0;)if((q=L[a/C].charAt(a%C))>46)for(b=a;b-->0;)if(L[b/C].charAt(b%C)==q){int y=b%C-a%C;if(p){g(2*a-b,a%C-y);g(2*b-a,b%C+y);}else for(int c=N;c-->0;)if((c/C-a/C)*y==(c%C-a%C)*(b/C-a/C))v[c]=1;}for(var z:v)n+=z;return n+"";}void g(int b,int c){if(b>=0&b<v.length&b%C==c)v[b]=1;}}
